// @ts-ignore .open-next/worker.js is generated by the OpenNext build.
import handler from "./.open-next/worker.js";

/**
 * Temporary diagnostic wrapper.
 * Inspect binding presence only; never return or log secret values.
 */
export default {
  async fetch(request: Request, env: unknown, ctx: unknown) {
    const bindings = env as Record<string, unknown>;
    const url = new URL(request.url);

    if (url.pathname === "/__runtime-binding-check") {
      const hasOpenRouterKey =
        typeof bindings.OPENROUTER_API_KEY === "string" &&
        bindings.OPENROUTER_API_KEY.length > 0;

      return Response.json(
        {
          service: "0xMan96 AI Worker binding diagnostic",
          runtimeBindings: {
            openRouterApiKey: hasOpenRouterKey,
            supabaseUrl: typeof bindings.NEXT_PUBLIC_SUPABASE_URL === "string",
            supabaseAnonKey: typeof bindings.NEXT_PUBLIC_SUPABASE_ANON_KEY === "string"
          },
          note: "Presence checks only. Secret values are never returned."
        },
        {
          headers: { "Cache-Control": "no-store" }
        }
      );
    }

    return handler.fetch(request, env, ctx);
  }
};
